def preparar_caja(apps, schema_editor):
    alias = schema_editor.connection.alias
    apps.get_model("inventario", "BloqueoCaja").objects.using(alias).create(pk=1)
    sesion = apps.get_model("inventario", "SesionCaja")
    tipo, _ = (
        apps.get_model("contenttypes", "ContentType")
        .objects.using(alias)
        .get_or_create(app_label="inventario", model="sesioncaja")
    )
    grupo, _ = (
        apps.get_model("auth", "Group")
        .objects.using(alias)
        .get_or_create(name="Administrador")
    )
    permisos = apps.get_model("auth", "Permission").objects.using(alias)
    for codigo, nombre in sesion._meta.permissions:
        permiso, _ = permisos.get_or_create(
            content_type=tipo, codename=codigo, defaults={"name": nombre}
        )
        grupo.permissions.add(permiso)


def retirar_permisos_caja(apps, schema_editor):
    sesion = apps.get_model("inventario", "SesionCaja")
    apps.get_model("auth", "Permission").objects.using(
        schema_editor.connection.alias
    ).filter(
        content_type__app_label="inventario",
        content_type__model="sesioncaja",
        codename__in=[codigo for codigo, _ in sesion._meta.permissions],
    ).delete()


